package com.personal.assistant.module.auth.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.common.security.JwtTokenService;import com.personal.assistant.module.auth.dto.*;import com.personal.assistant.module.auth.entity.UserAccount;import com.personal.assistant.module.auth.mapper.UserAccountMapper;import com.personal.assistant.module.security.service.SecurityAuditService;import jakarta.servlet.http.HttpServletRequest;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.*;
@Service public class AuthService{private static final ZoneId SHANGHAI=ZoneId.of("Asia/Shanghai");private final UserAccountMapper users;private final PasswordEncoder encoder;private final JwtTokenService tokens;private final SecurityAuditService audit;public AuthService(UserAccountMapper users,PasswordEncoder encoder,JwtTokenService tokens,SecurityAuditService audit){this.users=users;this.encoder=encoder;this.tokens=tokens;this.audit=audit;}public AuthService(UserAccountMapper users,PasswordEncoder encoder,JwtTokenService tokens){this(users,encoder,tokens,null);}
 @Transactional(noRollbackFor=BusinessException.class)public LoginResponse login(LoginRequest r,HttpServletRequest request){LocalDateTime now=LocalDateTime.now(SHANGHAI);UserAccount user=users.selectOne(new LambdaQueryWrapper<UserAccount>().eq(UserAccount::getUsername,r.username()).eq(UserAccount::getEnabled,true));if(user!=null&&user.getLockedUntil()!=null&&user.getLockedUntil().isAfter(now)){record(user.getId(),user.getUsername(),"LOGIN",false,"账户临时锁定",request);throw new BusinessException(ErrorCode.UNAUTHORIZED,"登录失败次数过多，请稍后再试");}if(user==null||!encoder.matches(r.password(),user.getPasswordHash())){if(user!=null){int failures=(user.getFailedLoginCount()==null?0:user.getFailedLoginCount())+1;user.setFailedLoginCount(failures);user.setLastFailedLoginAt(now);if(failures>=5){long minutes=Math.min(60,(long)Math.pow(2,Math.min(5,failures-5)));user.setLockedUntil(now.plusMinutes(minutes));}users.updateById(user);}record(user==null?null:user.getId(),r.username(),"LOGIN",false,"用户名或密码错误",request);throw new BusinessException(ErrorCode.UNAUTHORIZED,"用户名或密码错误");}user.setLastLoginTime(now);user.setFailedLoginCount(0);user.setLockedUntil(null);user.setLastFailedLoginAt(null);users.updateById(user);record(user.getId(),user.getUsername(),"LOGIN",true,null,request);return new LoginResponse(tokens.generateToken(user.getId(),user.getUsername()),user.getUsername(),user.getDisplayName(),user.getId());}
 @Transactional public void changePassword(Long uid,ChangePasswordRequest r,HttpServletRequest request){UserAccount user=users.selectById(uid);if(user==null||!Boolean.TRUE.equals(user.getEnabled()))throw new BusinessException(ErrorCode.UNAUTHORIZED);if(!encoder.matches(r.currentPassword(),user.getPasswordHash())){record(uid,user.getUsername(),"CHANGE_PASSWORD",false,"当前密码不正确",request);throw new BusinessException(ErrorCode.VALIDATION_ERROR,"当前密码不正确");}if(encoder.matches(r.newPassword(),user.getPasswordHash()))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"新密码不能与当前密码相同");user.setPasswordHash(encoder.encode(r.newPassword()));user.setUpdatedAt(LocalDateTime.now(SHANGHAI));users.updateById(user);record(uid,user.getUsername(),"CHANGE_PASSWORD",true,null,request);}public void changePassword(Long uid,ChangePasswordRequest r){changePassword(uid,r,null);}private void record(Long uid,String username,String operation,boolean success,String reason,HttpServletRequest request){if(audit!=null)audit.record(uid,username,operation,"ACCOUNT",uid==null?null:String.valueOf(uid),success,reason,request);}}
